<?php
function nstBankSaveBalance($db,$body,$user){
 $id=filter_var($body['IdCuenta']??null,FILTER_VALIDATE_INT);$date=(string)($body['FechaInicio']??'');$amount=$body['SaldoInicial']??null;$version=filter_var($body['Version']??null,FILTER_VALIDATE_INT);$reason=trim((string)($body['Motivo']??''));$today=(new DateTime('now',new DateTimeZone('America/Lima')))->format('Y-m-d');
 if(!$id||$id===1||!nstPayrollDate($date)||$date>$today||!is_numeric($amount)||!is_finite((float)$amount)||abs((float)$amount)>99999999||$version===false||$version<0||mb_strlen($reason)<5||mb_strlen($reason)>500)throw new InvalidArgumentException('Revise cuenta, fecha, saldo y motivo (mínimo 5 caracteres). La fecha no puede ser futura.');
 $db->beginTransaction();try{
  $q=$db->prepare('SELECT IdCuenta FROM Cb_Cuenta WHERE IdCuenta=? AND IdCuenta<>1 AND IFNULL(Anulado,0)=0 FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn())throw new InvalidArgumentException('Seleccione una cuenta bancaria activa.');
  $q=$db->prepare('SELECT * FROM Cb_SaldoBanco WHERE IdCuenta=? FOR UPDATE');$q->execute([$id]);$before=$q->fetch(PDO::FETCH_ASSOC);if(($before?(int)$before['Version']:0)!==$version)throw new InvalidArgumentException('El saldo fue modificado en otra ventana. Actualice antes de guardar.');
  $now=(new DateTime('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');$next=$version+1;$value=round((float)$amount,2);
  if($before){$q=$db->prepare('UPDATE Cb_SaldoBanco SET FechaInicio=?,SaldoInicial=?,Version=?,UsuarioMod=?,FechaMod=?,Motivo=? WHERE IdCuenta=?');$q->execute([$date,$value,$next,$user,$now,$reason,$id]);}
  else{$q=$db->prepare('INSERT INTO Cb_SaldoBanco(IdCuenta,FechaInicio,SaldoInicial,Version,UsuarioReg,FechaReg,Motivo) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$date,$value,$next,$user,$now,$reason]);}
  $after=['IdCuenta'=>$id,'FechaInicio'=>$date,'SaldoInicial'=>$value,'Version'=>$next];$q=$db->prepare('INSERT INTO Cb_SaldoBancoAuditoria(IdCuenta,Version,DatosAntes,DatosDespues,Usuario,Motivo,Fecha) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$next,$before?json_encode($before,JSON_UNESCAPED_UNICODE):null,json_encode($after,JSON_UNESCAPED_UNICODE),$user,$reason,$now]);$db->commit();return $after;
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
return function($app){
 $auth=function($q,$r,$action){if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=trim((string)($_SESSION['user']??''));if(empty($_SESSION['bank_csrf']))$_SESSION['bank_csrf']=bin2hex(random_bytes(24));$token=$_SESSION['bank_csrf'];session_write_close();if(!$user)return $r->withJson(['error'=>'Inicie sesión nuevamente.'],401);if(strtolower($user)!=='superadmin')return $r->withJson(['error'=>'Disponible solo para superadmin.'],403);if($q->getMethod()==='POST'&&!hash_equals($token,(string)$q->getParam('_csrf')))return $r->withJson(['error'=>'Actualice la página antes de guardar.'],403);try{return $action($user,$token);}catch(InvalidArgumentException $e){return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){error_log('[NST-SALDO-BANCOS] '.$e->getMessage());return $r->withJson(['error'=>'No se pudo guardar o consultar el saldo.'],500);}};
 $app->get('/bancos/saldos',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user,$token)use($r){$rows=$this->db->query('SELECT c.IdCuenta,c.Cuenta,c.Anulado,b.FechaInicio,b.SaldoInicial,IFNULL(b.Version,0) Version,b.UsuarioReg,b.FechaReg,b.UsuarioMod,b.FechaMod,b.Motivo FROM Cb_Cuenta c LEFT JOIN Cb_SaldoBanco b ON b.IdCuenta=c.IdCuenta WHERE c.IdCuenta<>1 ORDER BY c.Cuenta')->fetchAll(PDO::FETCH_ASSOC);$today=(new DateTime('now',new DateTimeZone('America/Lima')))->format('Y-m-d');$report=nstBankReportData($this->db,$today,$today);$totals=[];foreach($report['Cuentas'] as $g)$totals[$g['IdCuenta']]=$g['Saldo'];foreach($rows as &$row)$row['SaldoActual']=$totals[$row['IdCuenta']]??0;unset($row);return $r->withJson(['csrf'=>$token,'Fecha'=>$today,'Cuentas'=>$rows]);});});
 $app->post('/bancos/saldos',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){return $r->withJson(nstBankSaveBalance($this->db,$q->getParsedBody()?:[],$user));});});
 $app->get('/bancos/saldos/historial',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function()use($q,$r){$s=$this->db->prepare('SELECT IdAuditoria,IdCuenta,Version,DatosAntes,DatosDespues,Usuario,Motivo,Fecha FROM Cb_SaldoBancoAuditoria WHERE IdCuenta=? ORDER BY IdAuditoria DESC');$s->execute([(int)$q->getParam('cuenta')]);return $r->withJson($s->fetchAll(PDO::FETCH_ASSOC));});});
};
